    "level": "low",
    "touches": [
      "wallet",
      "tooling",
      "build"
    ],
    "why": "Affects only multiprocess builds behind compile-time flags; a failure would manifest as connection errors or crashes when running bitcoin-wallet with IPC enabled."
  }
